<a class="back" href="/events">← К мероприятиям</a><div class="panel form-panel"><span class="eyebrow">Новое событие</span><h1>Создать мероприятие</h1><form method="post" action="/events" novalidate>
<?php foreach (['title'=>'Название','date'=>'Дата','capacity'=>'Вместимость'] as $key=>$label): ?><label for="<?= e($key) ?>"><?= e($label) ?></label><input id="<?= e($key) ?>" name="<?= e($key) ?>" type="<?= $key === 'date' ? 'date' : ($key === 'capacity' ? 'number' : 'text') ?>" value="<?= e($old[$key] ?? '') ?>" <?= $key === 'capacity' ? 'min="1"' : '' ?>><small class="error"><?= e($errors[$key] ?? '') ?></small><?php endforeach; ?>
<label for="venue_id">Площадка</label><select id="venue_id" name="venue_id"><option value="">Выберите площадку</option><?php foreach ($venues as $venue): ?><option value="<?= e($venue['id']) ?>" <?= ($old['venue_id'] ?? '') === (string)$venue['id'] ? 'selected' : '' ?>><?= e($venue['name']) ?></option><?php endforeach; ?></select><small class="error"><?= e($errors['venue_id'] ?? '') ?></small>
<label for="status">Статус</label><select id="status" name="status"><?php foreach (['draft'=>'Черновик','published'=>'Опубликовано','completed'=>'Завершено'] as $key=>$label): ?><option value="<?= e($key) ?>" <?= ($old['status'] ?? 'draft') === $key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select><small class="error"><?= e($errors['status'] ?? '') ?></small>
<label for="description">Описание</label><textarea id="description" name="description" rows="4"><?= e($old['description'] ?? '') ?></textarea><button class="button" type="submit">Создать мероприятие</button></form></div>